Q: Tweak to working Javascript to make it read from textfield A: <p>Changes:</p>
<ol>
<li><p>Added an input for the route (parse &quot;Origin to Destination&quot;).</p>
</li>
<li><p>Parse input by splitting on &quot; to &quot; (case-insensitive).</p>
</li>
<li><p>Added a Calculate button.</p>
</li>
<li><p>Enter key triggers calculation.</p>
</li>
</ol>
<p>How to <strong>use:</strong></p>
<ul>
<li><p>Type: Nashville, TN to Atlanta, GA</p>
</li>
<li><p>Click &quot;Calculate Distance&quot; or press Enter.</p>
</li>
<li><p>The distance appears in the output field.</p>
</li>
</ul>
<p>The parser splits on &quot; to &quot; so variations like &quot;Nashville, TN to Atlanta, GA&quot; work. Make sure your Google Maps API key is in the script tag.</p>
<p>Use this version with an input field. Parse &quot;Origin to Destination&quot; and display the distance:</p>
<pre><code>&lt;!DOCTYPE html&gt;
&lt;html&gt;
&lt;head&gt;
    &lt;title&gt;Route Miles Only&lt;/title&gt;
    &lt;script src=&quot;https://maps.googleapis.com/maps/api/js?key=MY API GOES HERE&quot;&gt;&lt;/script&gt;
    &lt;style&gt;
        body { font-family: sans-serif; padding: 20px; }
        input { padding: 8px; width: 300px; font-weight: bold; margin: 5px 0; }
        button { padding: 8px 16px; margin: 5px 0; cursor: pointer; }
        .route-input { width: 400px; }
    &lt;/style&gt;
&lt;/head&gt;
&lt;body&gt;

    &lt;label&gt;Route (e.g., &quot;Nashville, TN to Atlanta, GA&quot;):&lt;/label&gt;&lt;br&gt;
    &lt;input type=&quot;text&quot; id=&quot;route-input&quot; class=&quot;route-input&quot; placeholder=&quot;Nashville, TN to Atlanta, GA&quot;&gt;&lt;br&gt;

    &lt;button onclick=&quot;calculateDistance()&quot;&gt;Calculate Distance&lt;/button&gt;&lt;br&gt;&lt;br&gt;

    &lt;label&gt;Total Route Distance:&lt;/label&gt;&lt;br&gt;
    &lt;input type=&quot;text&quot; id=&quot;distance-field&quot; readonly placeholder=&quot;Enter route and click Calculate&quot;&gt;

    &lt;script&gt;
        function calculateDistance() {
            const routeInput = document.getElementById('route-input').value.trim();
            const distanceField = document.getElementById('distance-field');

            // Parse the input - split on &quot; to &quot; or &quot; to&quot; or &quot;to &quot;
            const parts = routeInput.split(/\s+to\s+/i);

            if (parts.length !== 2) {
                distanceField.value = &quot;Error: Please use format 'City to City'&quot;;
                return;
            }

            const origin = parts[0].trim();
            const destination = parts[1].trim();

            if (!origin || !destination) {
                distanceField.value = &quot;Error: Both origin and destination required&quot;;
                return;
            }

            distanceField.value = &quot;Calculating...&quot;;

            const directionsService = new google.maps.DirectionsService();

            const request = {
                origin: origin,
                destination: destination,
                travelMode: 'DRIVING',
                unitSystem: google.maps.UnitSystem.IMPERIAL
            };

            directionsService.route(request, (result, status) =&gt; {
                if (status === 'OK') {
                    const miles = result.routes[0].legs[0].distance.text;
                    distanceField.value = miles;
                } else {
                    distanceField.value = &quot;Error: &quot; + status;
                }
            });
        }

        // Optional: Calculate on Enter key press
        document.getElementById('route-input').addEventListener('keypress', function(e) {
            if (e.key === 'Enter') {
                calculateDistance();
            }
        });
    &lt;/script&gt;
&lt;/body&gt;
&lt;/html&gt;

</code></pre>

Q: Forwarding C-style struct matrix to constructors of same-size matrix of objects A: <p>Tried the suggestion Emiloart., but it seems I can use the 2-dimensional array as internal structure, even without type conversion:</p>
<pre><code>#include &lt;utility&gt;
#include &lt;cstddef&gt;

struct RawData
{
    size_t val;
    const char *data_byte;
};

RawData testMatrix[4][4] =
{
    {{ 0, &quot; 1&quot;}, { 1, &quot; 2&quot;}, { 2, &quot; 3&quot;}, { 3, &quot; 4&quot;},},
    {{10, &quot; 5&quot;}, {11, &quot; 6&quot;}, {12, &quot; 7&quot;}, {13, &quot; 8&quot;},},
    {{20, &quot; 9&quot;}, {21, &quot;10&quot;}, {22, &quot;11&quot;}, {23, &quot;12&quot;},},
    {{30, &quot;13&quot;}, {31, &quot;14&quot;}, {32, &quot;15&quot;}, {33, &quot;16&quot;},},
};

struct TestElem
{
    const size_t value;
    const char *const data_byte;
    bool bChecked = false;

    explicit TestElem(const RawData &amp;Data)
        : value(Data.val),
          data_byte(Data.data_byte)
    {}
};

class TestMatrix
{
public:
    explicit TestMatrix(RawData Input[4][4])
        : TestMatrix(Input, std::make_index_sequence&lt;4 * 4&gt; {})
    {}

private:
    using MatrixType = TestElem [4][4];
    MatrixType matrix;

    template&lt;size_t... Is&gt;
    TestMatrix(RawData Input[4][4], std::index_sequence&lt;Is...&gt;)
        : matrix{TestElem(Input[Is / 4][Is % 4])...}
    {}
};

TestMatrix objTestMatrix(testMatrix);
</code></pre>
